import{_ as s,o as e,a as n,b as c}from"./app.DKoEZOcr.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"编译过程调试","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_debug"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_debug.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_debug.md","outlineHeaders":[{"level":2,"title":"生成代码调试","slug":"生成代码调试","link":"#生成代码调试"},{"level":3,"title":"生成产物目录","slug":"生成产物目录","link":"#生成产物目录"},{"level":3,"title":"常见问题排查场景","slug":"常见问题排查场景","link":"#常见问题排查场景"},{"level":3,"title":"强制重新生成","slug":"强制重新生成","link":"#强制重新生成"},{"level":2,"title":"Host侧编译调试","slug":"Host侧编译调试","link":"#Host侧编译调试"},{"level":3,"title":"方式一：构建时开启verbose","slug":"方式一：构建时开启verbose","link":"#方式一：构建时开启verbose"},{"level":3,"title":"方式二：cmake配置CMAKE_VERBOSE_MAKEFILE","slug":"方式二：cmake配置CMAKE_VERBOSE_MAKEFILE","link":"#方式二：cmake配置CMAKE_VERBOSE_MAKEFILE"},{"level":3,"title":"常见问题排查场景","slug":"常见问题排查场景-1","link":"#常见问题排查场景-1"},{"level":2,"title":"核函数（Kernel）侧编译调试","slug":"核函数（Kernel）侧编译调试","link":"#核函数（Kernel）侧编译调试"},{"level":3,"title":"开启方法","slug":"开启方法","link":"#开启方法"},{"level":3,"title":"保留的中间产物","slug":"保留的中间产物","link":"#保留的中间产物"},{"level":3,"title":"常见问题排查场景","slug":"常见问题排查场景-2","link":"#常见问题排查场景-2"},{"level":3,"title":"部分芯片编译失败处理","slug":"部分芯片编译失败处理","link":"#部分芯片编译失败处理"},{"level":2,"title":"打包与部署调试","slug":"打包与部署调试","link":"#打包与部署调试"},{"level":3,"title":"查看打包命令","slug":"查看打包命令","link":"#查看打包命令"},{"level":3,"title":"检查编译产物目录","slug":"检查编译产物目录","link":"#检查编译产物目录"},{"level":3,"title":"安装后验证内容","slug":"安装后验证内容","link":"#安装后验证内容"},{"level":3,"title":"常见问题排查场景","slug":"常见问题排查场景-3","link":"#常见问题排查场景-3"},{"level":2,"title":"编译日志存盘","slug":"编译日志存盘","link":"#编译日志存盘"}],"lastUpdated":1788139350000}'),t={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/compilation_debug.md"};function o(l,a,p,d,i,h){return e(),n("div",null,[...a[0]||(a[0]=[c(`<div><article class="markdown-body"><h1>编译过程调试</h1><p>本文是扩展内容，介绍算子工程编译过程中的调试方法。算子工程编译涉及代码生成、Host侧编译、核函数（Kernel）侧编译、打包部署四个阶段，默认输出通常不足以定位根因，下文按阶段介绍调试手段，并附常见错误的诊断方法。</p><h2 id="生成代码调试">生成代码调试<a class="header-anchor" href="#生成代码调试">​</a></h2><p><code>npu_op_code_gen</code>在cmake configure阶段自动生成aclnn调用代码和算子原型定义代码。生成产物位于<code>ASCEND_AUTOGEN_PATH</code>目录，默认是<code>&lt;CMAKE_BINARY_DIR&gt;/autogen</code>；按本文示例使用<code>build_out</code>时，对应目录为<code>build_out/autogen</code>。当原型定义有误或生成结果与预期不符时，需要检查这些文件。</p><h3 id="生成产物目录">生成产物目录<a class="header-anchor" href="#生成产物目录">​</a></h3><p>以AddCustom工程为例，配置完成后<code>build_out/autogen/</code>下会生成aclnn调用代码、算子原型定义代码和若干编译配置文件。下方仅列出排查代码生成问题时常用的关键产物；多算子工程会为每个算子生成对应的<code>aclnn_&lt;op&gt;.cpp</code>和<code>aclnn_&lt;op&gt;.h</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>build_out/autogen/
├── aclnn_add_custom.cpp      // aclnn调用代码实现
├── aclnn_add_custom.h        // aclnn调用代码头文件
├── op_proto.cc               // 算子原型定义代码（入图用）
├── op_proto.h                // 算子原型定义头文件
├── aic-&lt;soc&gt;-ops-info.ini    // 指定芯片型号的算子信息
├── custom_compile_options.ini
├── custom_opc_options.ini
└── ...
</code></pre></div><h3 id="常见问题排查场景">常见问题排查场景<a class="header-anchor" href="#常见问题排查场景">​</a></h3><table><thead><tr><th>问题</th><th>查看什么</th></tr></thead><tbody><tr><td>aclnn接口参数与原型定义不匹配</td><td>检查<code>aclnn_&lt;op&gt;.h</code>中的函数签名，确认输入输出和属性参数是否正确映射。</td></tr><tr><td>入图场景算子注册信息异常</td><td>检查<code>op_proto.cc</code>中的注册宏，确认OpType、dtype/format是否与Host侧定义一致。</td></tr><tr><td>某个算子的调用代码未生成</td><td>检查<code>npu_op_code_gen</code>的<code>SRC</code>参数是否包含了该算子的Host侧源文件。</td></tr><tr><td>JOIN_OP_DEF相关芯片型号异常</td><td><code>JOIN_OP_DEF=True</code>时算子构建阶段不再显式传入<code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>，需结合configure日志、<code>op_proto.cc</code>中的AddConfig和CMakePresets.json中的芯片型号确认目标型号是否被覆盖。</td></tr></tbody></table><h3 id="强制重新生成">强制重新生成<a class="header-anchor" href="#强制重新生成">​</a></h3><p>修改文件后，如果怀疑历史产物残留导致问题，可以手动清理后重新configure：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>rm<span class="w"> </span>-rf<span class="w"> </span>build_out/autogen
cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
</code></pre></div><h2 id="Host侧编译调试">Host侧编译调试<a class="header-anchor" href="#Host侧编译调试">​</a></h2><p>Host侧构建时，默认只输出编译目标的摘要信息，不显示实际执行的编译和链接命令。通过VERBOSE机制可以打印完整的命令行，用于排查头文件路径、链接库、编译选项等问题。</p><h3 id="方式一：构建时开启verbose">方式一：构建时开启verbose<a class="header-anchor" href="#方式一：构建时开启verbose">​</a></h3><p>在构建命令中指定verbose，打印每条编译和链接命令：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>--verbose<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>输出示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[ 30%] Building CXX object op_host/CMakeFiles/cust_opapi.dir/__/autogen/aclnn_add_custom.cpp.o
cd /data/asc-devkit/AddCustom/build_out/op_host &amp;&amp; /usr/bin/c++ -D_FORTIFY_SOURCE=2 -D_GLIBCXX_USE_CXX11_ABI=0 -I/usr/local/Ascend/cann-9.1.0/include -fvisibility=hidden -fPIC -fvisibility-inlines-hidden -O2 -fstack-protector-strong -MD -MT op_host/CMakeFiles/cust_opapi.dir/__/autogen/aclnn_add_custom.cpp.o -MF CMakeFiles/cust_opapi.dir/__/autogen/aclnn_add_custom.cpp.o.d -o CMakeFiles/cust_opapi.dir/__/autogen/aclnn_add_custom.cpp.o -c /data/asc-devkit/AddCustom/build_out/autogen/aclnn_add_custom.cpp
</code></pre></div><p>每行输出包含完整的编译器调用，可以看到：</p><ul><li>实际的编译器路径（如<code>/usr/bin/c++</code>）。</li><li>宏定义（<code>-D</code>）和头文件搜索路径（<code>-I</code>）。</li><li>编译选项（如<code>-fvisibility=hidden</code>、<code>-g</code>、<code>-O2</code>）。</li><li>链接库路径（<code>-L</code>）和链接库（<code>-l</code>）。</li></ul><h3 id="方式二：cmake配置CMAKE_VERBOSE_MAKEFILE">方式二：cmake配置CMAKE_VERBOSE_MAKEFILE<a class="header-anchor" href="#方式二：cmake配置CMAKE_VERBOSE_MAKEFILE">​</a></h3><p>在cmake configure阶段开启verbose，后续所有make调用都会自动打印完整命令：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DCMAKE_VERBOSE_MAKEFILE<span class="o">=</span>ON
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>与方式一效果相同，区别在于设置持久化在CMakeCache.txt中，无需每次构建时重复指定。</p><h3 id="常见问题排查场景-1">常见问题排查场景<a class="header-anchor" href="#常见问题排查场景-1">​</a></h3><table><thead><tr><th>问题</th><th>查看什么</th></tr></thead><tbody><tr><td>头文件找不到</td><td><code>-I</code>路径是否包含目标头文件所在目录。</td></tr><tr><td>链接undefined reference</td><td><code>-L</code>和<code>-l</code>是否包含缺失符号所在的库。</td></tr></tbody></table><h2 id="核函数（Kernel）侧编译调试">核函数（Kernel）侧编译调试<a class="header-anchor" href="#核函数（Kernel）侧编译调试">​</a></h2><p>核函数（Kernel）侧由编译框架为每个算子调用毕昇编译器，默认不保留中间产物。通过<code>--save-temp-files</code>选项可以保留每次编译的中间文件，用于排查预处理、编译、链接各阶段的问题。</p><h3 id="开启方法">开启方法<a class="header-anchor" href="#开启方法">​</a></h3><p>在核函数（Kernel）侧CMakeLists.txt中，通过<code>npu_op_kernel_options</code>添加<code>--save-temp-files</code>选项：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 为所有算子开启</span>
<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">ALL</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="p">)</span>

<span class="c"># 仅对特定算子开启</span>
<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustom</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="p">)</span>
</code></pre></div><p>也可以同时添加<code>-g</code>生成调试信息，配合使用：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">ALL</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="w"> </span><span class="s">-g</span><span class="p">)</span>
</code></pre></div><h3 id="保留的中间产物">保留的中间产物<a class="header-anchor" href="#保留的中间产物">​</a></h3><p>开启后，编译框架会在构建目录下保留每个核函数（Kernel）编译过程的中间文件。例如本文在ascendxxyy上验证的AddCustom工程中，临时文件位于：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>build_out/op_kernel/AddCustom_ascendxxyy/kernel_*/kernel_meta_&lt;kernel_name&gt;/kernel_meta/
</code></pre></div><p>实际目录名会随OpType、芯片型号和核函数（Kernel）名称变化。常见文件包括：</p><ul><li><strong>预处理文件</strong>（<code>.i</code>）：预处理后的源码，可用于确认宏展开是否正确、头文件是否被正确包含。</li><li><strong>目标文件</strong>（<code>.o</code>）：链接前的目标文件，可用于确认符号是否正确导出。</li><li><strong>编译日志</strong>（<code>.log</code>）：单个核函数（Kernel）的编译日志，可用于查看编译器调用和诊断信息。</li><li><strong>生成源码</strong>（<code>*_kernel.cpp</code>、<code>*_tiling_data.h</code>等）：编译框架生成的核函数（Kernel）源码和Tiling数据结构文件。</li></ul><h3 id="常见问题排查场景-2">常见问题排查场景<a class="header-anchor" href="#常见问题排查场景-2">​</a></h3><table><thead><tr><th>问题</th><th>查看什么</th></tr></thead><tbody><tr><td>宏定义未生效</td><td>检查<code>.i</code>文件，确认宏是否被正确展开。</td></tr><tr><td>头文件包含缺失</td><td>检查<code>.i</code>文件，确认目标头文件的内容是否被引入。</td></tr><tr><td>链接符号缺失</td><td>检查<code>.o</code>文件的符号表（<code>nm</code>命令），确认目标符号是否存在。</td></tr></tbody></table><h3 id="部分芯片编译失败处理">部分芯片编译失败处理<a class="header-anchor" href="#部分芯片编译失败处理">​</a></h3><p>当<code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>配置了多个芯片型号时，核函数（Kernel）编译会对每个芯片独立执行一轮。如果某个芯片的核函数（Kernel）编译失败，默认行为是终止整个构建流程。</p><p><code>ASCEND_SKIP_FAILED_COMPUTE_UNIT</code>选项允许跳过单个芯片的编译失败，继续编译其余芯片。适用场景：</p><ul><li>算子对某些芯片型号尚不完全适配，但其他型号已可正常使用。</li><li><code>npu_op_code_gen</code>的<code>JOIN_OP_DEF</code>参数设为False时，用户通过compute_unit自行设置芯片型号，算子对其中部分型号缺少适配。</li></ul><p><strong>配置方法</strong>：在CMakeLists.txt中设置：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">set</span><span class="p">(</span><span class="s">ASCEND_SKIP_FAILED_COMPUTE_UNIT</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
</code></pre></div><p>或在cmake命令行中传入：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span>-DASCEND_SKIP_FAILED_COMPUTE_UNIT<span class="o">=</span>TRUE
</code></pre></div><p>开启该选项后，部分AI处理器型号对应的算子编译失败时，编译流程可跳过失败项并继续编译其他型号；关闭时，遇到失败会影响其他型号的编译流程。若需要定位被跳过的失败项，建议同时配置<a href="#%E7%BC%96%E8%AF%91%E6%97%A5%E5%BF%97%E5%AD%98%E7%9B%98">ASCENDC_BUILD_LOG_DIR</a>保存编译日志。</p><h2 id="打包与部署调试">打包与部署调试<a class="header-anchor" href="#打包与部署调试">​</a></h2><p>打包阶段将编译产物组织为<code>.run</code>安装包，部署阶段将算子包安装到目标环境。打包或安装出问题时，检查中间产物和打包命令即可定位。</p><h3 id="查看打包命令">查看打包命令<a class="header-anchor" href="#查看打包命令">​</a></h3><p>与Host侧调试一样，使用VERBOSE机制可以看到实际的打包命令：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>package<span class="w"> </span>--verbose<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>输出示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Run CPack packaging tool...
/opt/buildtools/cmake-3.20.5-linux-aarch64/bin/cpack --config ./CPackConfig.cmake
</code></pre></div><p>可以看到cpack调用过程，用于排查打包配置问题。</p><h3 id="检查编译产物目录">检查编译产物目录<a class="header-anchor" href="#检查编译产物目录">​</a></h3><p>在打包或安装前，先检查编译产物目录，确认单算子API头文件、动态库、核函数（Kernel）二进制和Tiling库等是否已生成。不同编译方式下目录结构会有差异，下方仅列出排查时常用的关键路径。</p><p><code>TYPE RUN</code>模式下，原始构建目录中主要检查中间产物：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>build_out/
├── autogen/
│   ├── aclnn_add_custom.h
│   └── ...
├── op_host/
│   ├── libcust_opapi.so
│   ├── libcust_opmaster_rt2.0.so
│   ├── libcust_opsproto_rt2.0.so
│   └── ...
├── op_kernel/ascendc_kernels/binary/
│   ├── ascendxxyy/
│   │   └── add_custom/
│   ├── config/ascendxxyy/
│   ├── dynamic/
│   └── ...
└── ...
</code></pre></div><p>执行<code>package</code>目标后，CPack staging目录中会出现接近安装后形态的<code>vendors/&lt;vendor_name&gt;/</code>目录，可重点检查<code>op_api/</code>、<code>op_impl/</code>、<code>op_proto/</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>build_out/_CPack_Packages/Linux/External/custom_opp_*.run/packages/vendors/&lt;vendor_name&gt;/
├── op_api/
│   ├── include/aclnn_&lt;op&gt;.h
│   └── lib/libcust_opapi.so
├── op_impl/
│   ├── ai_core/tbe/
│   └── ...
├── op_proto/
│   ├── inc/op_proto.h
│   └── lib/linux/aarch64/libcust_opsproto_rt2.0.so
└── ...
</code></pre></div><p><code>TYPE SHARED</code>或<code>TYPE STATIC</code>安装模式下，产物通常位于<code>\${CMAKE_INSTALL_PREFIX}/include</code>和<code>\${CMAKE_INSTALL_PREFIX}/lib</code>。</p><p><strong>检查要点</strong>：</p><ul><li><code>build_out/autogen/</code>或staging目录的<code>op_api/include/</code>下是否生成<code>aclnn_&lt;op&gt;.h</code>。</li><li><code>build_out/op_host/</code>或staging目录的<code>op_api/lib/</code>下是否生成<code>libcust_opapi.so</code>。</li><li>staging目录或安装目录的<code>op_impl</code>下是否包含目标芯片型号的核函数（Kernel）二进制和Tiling动态库。</li><li>如果使用SHARED/STATIC模式，<code>ENABLE_BINARY_PACKAGE</code>必须为True。</li></ul><h3 id="安装后验证内容">安装后验证内容<a class="header-anchor" href="#安装后验证内容">​</a></h3><p>安装<code>.run</code>包后，可在安装目录下检查部署结果。默认安装场景检查：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ls<span class="w"> </span><span class="si">\${</span><span class="nv">INSTALL_DIR</span><span class="si">}</span>/opp/vendors/&lt;vendor_name&gt;/op_api
ls<span class="w"> </span><span class="si">\${</span><span class="nv">INSTALL_DIR</span><span class="si">}</span>/opp/vendors/&lt;vendor_name&gt;/op_impl
ls<span class="w"> </span><span class="si">\${</span><span class="nv">INSTALL_DIR</span><span class="si">}</span>/opp/vendors/&lt;vendor_name&gt;/op_proto<span class="w"> </span><span class="c1"># 可选</span>
</code></pre></div><p>指定目录安装场景检查：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ls<span class="w"> </span>&lt;path&gt;/vendors/&lt;vendor_name&gt;/op_api
ls<span class="w"> </span>&lt;path&gt;/vendors/&lt;vendor_name&gt;/op_impl
ls<span class="w"> </span>&lt;path&gt;/vendors/&lt;vendor_name&gt;/op_proto<span class="w"> </span><span class="c1"># 可选</span>
</code></pre></div><h3 id="常见问题排查场景-3">常见问题排查场景<a class="header-anchor" href="#常见问题排查场景-3">​</a></h3><table><thead><tr><th>问题</th><th>查看什么</th></tr></thead><tbody><tr><td><code>package</code>目标失败</td><td><code>cmake --build build_out --target package --verbose</code>输出中cpack的命令和报错信息。</td></tr><tr><td>SHARED/STATIC模式下构建或安装报错</td><td><code>npu_op_package</code> CONFIG中<code>ENABLE_BINARY_PACKAGE</code>是否为True。</td></tr><tr><td>INSTALL_PATH生成产物位置不对</td><td><code>npu_op_package</code> CONFIG中<code>INSTALL_PATH</code>配置是否指向预期目录。</td></tr><tr><td>安装后算子未被识别</td><td>指定目录安装时是否执行了<code>source &lt;path&gt;/vendors/&lt;vendor_name&gt;/bin/set_env.bash</code>，默认安装时<code>opp/vendors/config.ini</code>中优先级配置是否正确。</td></tr></tbody></table><h2 id="编译日志存盘">编译日志存盘<a class="header-anchor" href="#编译日志存盘">​</a></h2><p>默认情况下，核函数（Kernel）侧编译过程中的中间日志不会保留到磁盘，编译失败时终端仅打印异常抛出信息。通过设置<code>ASCENDC_BUILD_LOG_DIR</code>环境变量，可将每个编译阶段的日志写入指定目录，便于事后回溯。</p><p><strong>开启方法</strong>：在执行cmake或build.sh之前设置环境变量：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">export</span><span class="w"> </span><span class="nv">ASCENDC_BUILD_LOG_DIR</span><span class="o">=</span>/home/build_log/
</code></pre></div><p>编译框架会在其下按芯片型号创建子目录。例如编译<code>ascendxxyy</code>和<code>ascendxxyy_2</code>两个芯片时，日志目录结构为：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>/home/build_log/
├── ascendxxyy/
└── ascendxxyy_2/
</code></pre></div><p><strong>日志命名规则</strong>：开启日志存盘后，编译框架会根据编译结果调整日志文件后缀：</p><ul><li><strong>编译成功</strong>：对应日志文件后缀会添加<code>_success</code>。</li><li><strong>编译失败</strong>：终端会打印错误信息和对应日志文件路径，日志文件后缀会添加<code>_error</code>。</li></ul><p><strong>从日志定位错误</strong>：</p><ol><li>在终端报错中查看失败日志的具体路径，或在<code>ASCENDC_BUILD_LOG_DIR</code>对应芯片子目录下搜索带<code>_error</code>后缀的日志文件。</li><li>打开失败日志，查看毕昇编译器输出的错误信息。</li><li>根据错误中的文件名、行号或API提示回到源码修正。</li></ol><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>开启<code>ASCEND_SKIP_FAILED_COMPUTE_UNIT</code>时，建议同时开启<code>ASCENDC_BUILD_LOG_DIR</code>，两者配合使用可以完整保留每个失败核函数（Kernel）的详细编译日志，便于逐个修复。</p></div></article></div>`,1)])])}const _=s(t,[["render",o]]);export{v as __pageData,_ as default};
